--

CREATE FUNCTION schema_emswms.containerbywarehouseandowner(warehouses character varying, startdate character varying, enddate character varying) RETURNS TABLE(warehouse character varying, owner character varying, count bigint)
    LANGUAGE plpgsql
    AS $_$
BEGIN
 
RETURN QUERY SELECT 
w.wrh_warehousecode, o.own_ownercode,count(c.stk_containerid) 
FROM schema_emswms.own_owner o 
JOIN schema_emswms.stk_container c ON o.own_ownerid = c.stk_containerownerid 
JOIN schema_emswms.wrh_warehouse w ON c.stk_containerwarehouseid = w.wrh_warehouseid 
WHERE c.stk_containerreceptiondate >= to_date(startDate, 'DD/mm/YYYY')
AND c.stk_containerreceptiondate <= to_date(endDate, 'DD/mm/YYYY')
AND ($1 = '*' OR w.wrh_warehousecode = any( regexp_split_to_array($1, ',')))  
GROUP BY w.wrh_warehousecode, o.own_ownercode;
END; $_$;


