--
-- TOC entry 9082 (class 1255 OID 4030810)
-- Name: countstoredcontainers(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: schema_emswms; Owner: postgres
--

CREATE FUNCTION schema_emswms.countstoredcontainers(hallcode character varying, aislecode character varying, zonecode character varying, rackcode character varying, workzone character varying) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
BEGIN
 
 RETURN (
	select count(cnt.stk_containerid) as count from schema_emswms.stk_container cnt
	 LEFT JOIN schema_emswms.loc_location loc on cnt.stk_containerlocationid=loc.loc_locationid 
	 LEFT JOIN schema_emswms.loc_hall hall ON hall.loc_hallid=loc.loc_locationhallid 
 	 LEFT JOIN schema_emswms.loc_rack rack ON rack.loc_rackid=loc.loc_locationrackid 
     LEFT JOIN schema_emswms.loc_aisle aisle ON aisle.loc_aisleid=rack.loc_rackaisleinid 
	 LEFT JOIN schema_emswms.loc_zone zone ON zone.loc_zoneid=loc.loc_locationzoneid 
	 LEFT JOIN schema_emswms.loc_zonework zonework ON zonework.loc_zoneworkid=loc.loc_locationworkzoneid
	where  stk_containeractive=true  AND ($1 ='*' or hall.loc_hallcode = $1) AND ($4 ='*' or  rack.loc_rackcode = $4) 
	AND ($2 ='*' or  aisle.loc_aislecode = $2) AND ($3 ='*' or  zone.loc_zonecode = $3)  AND ($5 ='*' or  zonework.loc_zoneworkcode = $5)
	and loc.loc_locationlocationtypeid in (6,7) and loc_locationcellid is not null
 );
END; 
$_$;


