    LANGUAGE plpgsql
    AS $_$
BEGIN
 
RETURN QUERY  
SELECT o.own_ownercode, to_char(inv_invoicedatainvoicedate, 'DD/mm/YYYY'), sum (inv_invoicedatatotalprice) 
