--

CREATE FUNCTION schema_emswms.orderedquantity(id numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$ 
BEGIN
RETURN(
select COALESCE(sum(COALESCE(cmd_saleorderline.cmd_saleorderlinequantity*pdt_productpackquantity, 0::numeric) - COALESCE(cmd_saleorderline.cmd_saleorderlinequantityserved*pdt_productpackquantity, 0::numeric)), 0::numeric) 
  from 
schema_emswms.cmd_saleorderline,schema_emswms.cmd_saleorder,schema_emswms.pdt_product,schema_emswms.pdt_productpack where 
(cmd_saleorderline.cmd_saleorderlinestatusid <> ALL (ARRAY[1::numeric, 3::numeric, 4::numeric])) AND cmd_saleorderline.cmd_saleorderlineproductid = pdt_product.pdt_productid
and cmd_saleorder.cmd_saleorderid = cmd_saleorderline.cmd_saleorderlineorderid AND cmd_saleorder.cmd_saleorderactive = true and pdt_productpackid=cmd_saleorderlinepackid);
END; $$;


