AND prm_orderstatusid = rcp_purshaseorderstatusid
AND prm_orderstatusid = any (regexp_split_to_array($3, ',')::numeric[]) 
GROUP BY wrh_warehousecode, own_ownercode, prm_orderstatusid;
END; $_$;


