--

CREATE FUNCTION schema_emswms.residuesorderline() RETURNS numeric
    LANGUAGE plpgsql
    AS $$
 

BEGIN

RETURN(
select count(cmd_saleorderlineid)
from schema_emswms.cmd_saleorderline,
schema_emswms.pdt_productpack 
where 
pdt_productpackid=cmd_saleorderlinepackid 
and cmd_saleorderlinequantity*pdt_productpackquantity>schema_emswms.stockedinwarehousequantity(cmd_saleorderlineproductid,cmd_saleorderlinewarehouseid)
and schema_emswms.stockedinwarehousequantity(cmd_saleorderlineproductid,cmd_saleorderlinewarehouseid)>0

);
END; 
$$;


