--

CREATE FUNCTION schema_emswms.saleorderassignment(id numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
BEGIN

RETURN  (

select sum(COALESCE(stk_stockreservedquantity,0))/(select sum(COALESCE(cmd_saleorderlinequantity,1)) from schema_emswms.cmd_saleorderline where cmd_saleorderlineorderid=$1)*100 from schema_emswms.stk_stockreserved
where stk_stockreservedorder_id=$1);
END; $_$;


ALTER FUNCTION schema_emswms.saleorderassignment(id numeric) OWNER TO postgres;

--
-- TOC entry 9110 (class 1255 OID 4030838)
