--

CREATE FUNCTION schema_emswms.saleorderassignment(id numeric, accoutid numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
BEGIN

RETURN  (

select (COALESCE(sum(stk_stockreservedbasequantity),0)+
(select COALESCE(sum(stk_manualstockreservedbasequantity),0) from schema_emswms.stk_manualstockreserved where (stk_manuelstockreservedorderid=$1) or( stk_manuelstockreservedaccountid=$2 and stk_manuelstockreservedorderid is null))
)
/1--(select sum(COALESCE(cmd_saleorderlinequantity,1)/pdt_productpackquantity) from schema_emswms.cmd_saleorderline,schema_emswms.pdt_productpack where cmd_saleorderlineorderid=$1 and cmd_saleorderlinepackid=pdt_productpackid)
*100 from schema_emswms.stk_stockreserved
where stk_stockreservedorder_id=$1);
END; $_$;


