--
-- TOC entry 9118 (class 1255 OID 4030846)
-- Name: stockagemovement(numeric, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: schema_emswms; Owner: postgres
--

CREATE FUNCTION schema_emswms.stockagemovement(ownerid numeric, startdate timestamp with time zone, enddate timestamp with time zone) RETURNS SETOF double precision
    LANGUAGE plpgsql
    AS $_$
BEGIN
 RETURN QUERY SELECT
sum(countC) FROM
(
(SELECT sum(DATE_PART ('day',$3 - date_trunc('day',
con.stk_containerreceptiondate) )) countC from schema_emswms.stk_container
con
where con.stk_containerreceptiondate > $2
AND con.stk_containerreceptiondate <= $3
AND con.stk_containeroutbounddate is null
AND con.stk_containerownerid=$1)
UNION ALL
(SELECT sum(DATE_PART ('day',$3 - $2)) countC from
schema_emswms.stk_container con
where con.stk_containerreceptiondate <= $2
AND con.stk_containerreceptiondate <= $3
AND con.stk_containeroutbounddate is null
AND con.stk_containerownerid=$1)
UNION ALL
(SELECT sum(DATE_PART ('day', date_trunc('day',
con.stk_containeroutbounddate) - date_trunc('day',
con.stk_containerreceptiondate) )) countC from schema_emswms.stk_container
con
where con.stk_containerreceptiondate > $2
AND con.stk_containerreceptiondate <= $3
AND con.stk_containeroutbounddate is not null
AND con.stk_containerownerid=$1)
UNION ALL
(SELECT sum(DATE_PART ('day', date_trunc('day',
con.stk_containeroutbounddate) - $2)) countC from
schema_emswms.stk_container con
where con.stk_containerreceptiondate <= $2
AND con.stk_containerreceptiondate <= $3
AND con.stk_containeroutbounddate is not null
AND con.stk_containerownerid=$1)
) AS storage_by_owner;
END; $_$;


ALTER FUNCTION schema_emswms.stockagemovement(ownerid numeric, startdate timestamp with time zone, enddate timestamp with time zone) OWNER TO postgres;

