--

CREATE FUNCTION schema_emswms.stockedinwarehousequantity(id numeric, warehouseid numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN(
select coalesce( coalesce(sum(stk_stockquantitybaseuom),0)- (sum(schema_emswms.stockedreservedquantity(stk_stockid))+sum(schema_emswms.stockedreservedmanualyquantity(stk_stockid))),0)  from 
schema_emswms.stk_stock where 
 stk_stockproductid=id  and stk_stockwarehouseid=warehouseId and stkstockactive=true);
END;
$$;


