    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN(
select coalesce(sum(stk_stockquantitybaseuom),0)-schema_emswms.productreservedmanualyquantity(id)-schema_emswms.productreservedquantity(id) from 
schema_emswms.stk_stock where 
 stk_stockproductid=id  and stkstockactive=true );
END;
$$;


ALTER FUNCTION schema_emswms.stockedquantity(id numeric) OWNER TO postgres;

