--

CREATE FUNCTION schema_emswms.stockedquantity(id numeric, warehouseid numeric, blocktypeid numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN(
select coalesce(sum(stk_stockquantitybaseuom),0)-schema_emswms.productreservedmanualyquantity(id,warehouseId,blocktypeid)-schema_emswms.productreservedquantity(id,warehouseId,blocktypeid)
	-schema_emswms.stockedquantitytoreserve(id,warehouseid)
	from 
schema_emswms.stk_stock where 
 stk_stockproductid=id  and stkstockactive=true and stk_stockwarehouseid=warehouseId and (stk_stockblockid=blocktypeId or blocktypeId=0)  and stk_stockstatusid!=8);
END;
$$;


ALTER FUNCTION schema_emswms.stockedquantity(id numeric, warehouseid numeric, blocktypeid numeric) OWNER TO postgres;

--
-- TOC entry 9123 (class 1255 OID 4030851)
-- Name: stockedquantitytoreserve(numeric, numeric); Type: FUNCTION; Schema: schema_emswms; Owner: postgres
--

CREATE FUNCTION schema_emswms.stockedquantitytoreserve(id numeric, warehouseid numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN(
SELECT  coalesce(sum(rcp_purshaseorderreservationquantity*pdt_productpackquantity),0)
	FROM schema_emswms.rcp_purshaseorderreservation,
	schema_emswms.pdt_productpack,
	schema_emswms.rcp_purshaseorderline,
	schema_emswms.rcp_purshaseorder

	where pdt_productpackid= rcp_purshaseorderreservationproductpackid
	and rcp_purshaseorderreservationactive=true
	and rcp_purshaseorderreservationpurchaselinenumber=rcp_purshaseorderlinenumber
	and rcp_purshaseordercode=rcp_purshaseorderreservationpurchasecode
	and rcp_purshaseorderid=rcp_purshaseorderlinepoid
	and rcp_purshaseorderlinewarehouseid=warehouseid
	and rcp_purshaseorderreservationproductid=id
	);
END;
$$;


