--
-- TOC entry 9124 (class 1255 OID 4030852)
-- Name: stockedreservedmanualyquantity(numeric); Type: FUNCTION; Schema: schema_emswms; Owner: postgres
--

CREATE FUNCTION schema_emswms.stockedreservedmanualyquantity(id numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$ 
BEGIN
RETURN(
select coalesce(sum(stk_manuelstockreservedquantity/coalesce(pdt_productpackquantity,1)),0)  from 
schema_emswms.stk_manualstockreserved,schema_emswms.pdt_productpack where
 stk_manuelstockreservedstockid=id and pdt_productpackid=stk_manuelstockreservedpackid);
END; $$;


