--
-- TOC entry 9128 (class 1255 OID 4030856)
-- Name: stockquantitybyuombase(); Type: FUNCTION; Schema: schema_emswms; Owner: postgres
--

CREATE FUNCTION schema_emswms.stockquantitybyuombase() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare 
quatity numeric;
    BEGIN
    select pdt_productpackquantity into quatity from schema_emswms2.pdt_productpack where pdt_productpackpdtid=NEW.stk_stockproductid and NEW.stk_stockuomid= pdt_productpackuomid;
 NEW.stk_stockquantitybaseuom := NEW.stk_stockquantity*quatity;
    return NEW;
    END;
$$;


