--
-- TOC entry 9129 (class 1255 OID 4030857)
-- Name: unique_container(); Type: FUNCTION; Schema: schema_emswms; Owner: postgres
--

CREATE FUNCTION schema_emswms.unique_container() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
	declare 
	countA numeric;
    BEGIN
    select count(*) into countA from schema_emswms.stk_container where stk_containercode=NEW.stk_containercode and stk_containerownerid=NEW.stk_containerownerid and stk_containeractive =true ;
        IF (countA>0) THEN
            RAISE EXCEPTION 'Conteneur exist déja(%)', NEW.stk_containercode;
        END IF;
        RETURN NEW;
    END;
$$;


ALTER FUNCTION schema_emswms.unique_container() OWNER TO postgres;

