--
-- TOC entry 7629 (class 1259 OID 4031003)
-- Name: container_view; Type: VIEW; Schema: schema_emswms; Owner: postgres
--

CREATE VIEW schema_emswms.container_view AS
 SELECT container.stk_containerid,
    container.stk_containercode,
    container.stk_containerlocationid,
    container.stk_containerreceptiondate,
    container.stk_containerwarehouseid,
    container.stk_containerownerid,
    container.stk_containerupdatedate,
    container.stk_containervariable1,
    container.stk_containervariable2,
    container.stk_containervariable3,
    container.stk_containervariable4,
    container.stk_containervariable5,
    container.stk_containervariable6,
    container.stk_containervariable7,
    container.stk_containervariable8,
    container.stk_containervariable9,
    container.stk_containervariable10,
    container.stk_containercreationdate
   FROM schema_emswms.stk_container container
  WHERE (container.stk_containerid IN ( SELECT stk.stk_stockcontainerid
           FROM schema_emswms.stk_stock stk
          WHERE (NOT (stk.stk_stockid IN ( SELECT stk.stk_stockid
                   FROM schema_emswms.cmd_saleorderstock salestock,
                    schema_emswms.cmd_delivery deliv
                  WHERE ((stk.stk_stockid = salestock.cmd_saleorderstockstockid) AND (deliv.cmd_deliveryid = salestock.cmd_saleorderstockdeliveryid) AND (deliv.cmd_deliveryorderstatusid = ANY (ARRAY[(1)::numeric, (4)::numeric]))))))));


ALTER TABLE schema_emswms.container_view OWNER TO postgres;

