--
-- TOC entry 7658 (class 1259 OID 4031151)
-- Name: loc_locationview; Type: VIEW; Schema: schema_emswms; Owner: postgres
--

CREATE VIEW schema_emswms.loc_locationview AS
 SELECT loc_location.loc_locationid,
    loc_location.loc_locationcode,
    loc_location.loc_locationzoneid,
    loc_location.loc_locationwarehouseid,
    loc_location.loc_locationisactive,
    loc_location.loc_locationcreationdate,
    loc_location.loc_locationupdatedate,
    loc_location.loc_locationpicking,
    loc_location.loc_locationreserve,
    loc_location.loc_locationlocationstatusid,
    loc_location.loc_locationorderstatusid,
    loc_location.loc_locationdefault,
    loc_location.loc_locationwmsid,
    loc_location.loc_locationflow,
    loc_location.createdby,
    loc_location.updatedby,
    loc_location.createdbyuserid,
    loc_location.updatedbyuserid,
    loc_location.loc_locationrackid,
    loc_location.loc_locationaisleinid,
    loc_location.loc_locationaisleoutid,
    loc_location.loc_locationstationid,
    loc_location.loc_locationorder,
    loc_location.loc_locationx,
    loc_location.loc_locationy,
    loc_location.loc_locationz,
    loc_location.loc_locationlocationtypeid,
    loc_location.loc_locationempty,
    loc_location.loc_locationblocked,
    loc_location.loc_locationcellid,
    loc_location.loc_locationworkzoneid,
    loc_location.loc_locationracktypeid,
    loc_location.loc_locationorderinventoringpath,
    loc_location.loc_locationorderstoragepath,
    loc_location.loc_locationorderpickingpath,
    loc_location.loc_locationusedforexpedition,
    loc_location.loc_locationusedforreception,
    loc_location.loc_locationdepth,
    loc_location.loc_locationheight,
    loc_location.loc_locationmaxweight,
    loc_location.loc_locationwidth,
        CASE
            WHEN (((( SELECT count(*) AS count
               FROM schema_emswms.tsk_task
              WHERE ((tsk_task.tsk_tasklocationtoid)::numeric = loc_location.loc_locationid)) > 0) OR (( SELECT count(*) AS count
               FROM schema_emswms.tsk_pendingtask
              WHERE ((tsk_pendingtask.tsk_tasklocationtoid)::numeric = loc_location.loc_locationid)) > 0)) AND (loc_location.loc_locationlocationtypeid = ANY (ARRAY[(6)::bigint, (7)::bigint]))) THEN true
            ELSE false
        END AS loc_locationreserved,
    loc_location.loc_locationhallid
   FROM schema_emswms.loc_location loc_location;


ALTER TABLE schema_emswms.loc_locationview OWNER TO postgres;

