--
-- TOC entry 7689 (class 1259 OID 4031315)
-- Name: pdt_productmouvementview; Type: VIEW; Schema: schema_emswms; Owner: postgres
--

CREATE VIEW schema_emswms.pdt_productmouvementview AS
 WITH p AS (
         SELECT pdt_product.pdt_productcode AS product,
            own_owner.own_ownercode AS owner,
            cmd_saleorderstock.cmd_saleorderstocklot AS lot,
                CASE
                    WHEN (cmd_saleorderstock.cmd_saleorderstockorderdate IS NOT NULL) THEN cmd_saleorderstock.cmd_saleorderstockorderdate
                    ELSE cmd_saleorderstock.cmd_saleorderstockcreationdate
                END AS creationdate,
            'Livraison'::text AS mouvementtype,
            (- cmd_saleorderstock.cmd_saleorderstockquantityserved) AS quantity,
            pdt_uom.pdt_uomcode AS uom,
            cmd_delivery.cmd_deliverycode AS code
           FROM ((((schema_emswms.cmd_saleorderstock
             LEFT JOIN schema_emswms.pdt_product ON ((cmd_saleorderstock.cmd_saleorderstockproductid = pdt_product.pdt_productid)))
             LEFT JOIN schema_emswms.own_owner ON ((own_owner.own_ownerid = cmd_saleorderstock.cmd_saleorderstockownerid)))
             LEFT JOIN schema_emswms.pdt_uom ON ((cmd_saleorderstock.cmd_saleorderstockuomid = pdt_uom.pdt_uomid)))
             LEFT JOIN schema_emswms.cmd_delivery ON ((cmd_saleorderstock.cmd_saleorderstockdeliveryid = cmd_delivery.cmd_deliveryid)))
        UNION ALL
         SELECT pdt_product.pdt_productcode AS product,
            own_owner.own_ownercode AS owner,
            rcp_receptionstock.rcp_receptionstocklot AS lot,
                CASE
                    WHEN (rcp_receptionstock.rcp_receptionstockreceptiondate IS NOT NULL) THEN rcp_receptionstock.rcp_receptionstockreceptiondate
                    ELSE rcp_receptionstock.rcp_receptionstockcreationdate
                END AS creationdate,
            'Réception'::text AS mouvementtype,
            rcp_receptionstock.rcp_receptionstockquantityreceived AS quantity,
            pdt_uom.pdt_uomcode AS uom,
            rcp_reception.rcp_receptioncode AS code
           FROM ((((schema_emswms.rcp_receptionstock
             LEFT JOIN schema_emswms.pdt_product ON ((rcp_receptionstock.rcp_receptionstockproductid = pdt_product.pdt_productid)))
             LEFT JOIN schema_emswms.own_owner ON ((own_owner.own_ownerid = rcp_receptionstock.rcp_receptionstockownerid)))
             LEFT JOIN schema_emswms.pdt_uom ON ((pdt_uom.pdt_uomid = rcp_receptionstock.rcp_receptionstockuomid)))
             LEFT JOIN schema_emswms.rcp_reception ON ((rcp_receptionstock.rcp_receptionstockreceptionid = rcp_reception.rcp_receptionid)))
        UNION ALL
         SELECT pdt_product.pdt_productcode AS product,
            own_owner.own_ownercode AS owner,
            stk_stock_exception.stk_stockexceptionlot AS lot,
            stk_stock_exception.stk_stockexceptioncreationdatenew AS creationdate,
            'Exception'::text AS mouvementtype,
            (stk_stock_exception.stk_stockexceptionquantitynew - stk_stock_exception.stk_stockexceptionquantity) AS quantity,
            pdt_uom.pdt_uomcode AS uom,
            ''::character varying AS code
           FROM (((schema_emswms.stk_stock_exception
             LEFT JOIN schema_emswms.pdt_product ON (((stk_stock_exception.stk_stockexceptionproductid)::numeric = pdt_product.pdt_productid)))
             LEFT JOIN schema_emswms.own_owner ON ((own_owner.own_ownerid = (stk_stock_exception.stk_stockexceptionownerid)::numeric)))
             LEFT JOIN schema_emswms.pdt_uom ON ((pdt_uom.pdt_uomid = (stk_stock_exception.stk_stockexceptionuomnewid)::numeric)))
        )
 SELECT row_number() OVER () AS row_number,
    p.product,
    p.owner,
    p.lot,
    p.creationdate,
    p.mouvementtype,
    p.quantity,
    p.uom,
    p.code
   FROM p
  WHERE ((p.quantity <> (0)::numeric) AND (p.product IS NOT NULL))
  ORDER BY p.creationdate DESC;


ALTER TABLE schema_emswms.pdt_productmouvementview OWNER TO postgres;

