--
-- TOC entry 29377 (class 2618 OID 4031227)
-- Name: ntf_product_stock _RETURN; Type: RULE; Schema: schema_emswms; Owner: postgres
--

CREATE OR REPLACE VIEW schema_emswms.ntf_product_stock AS
 SELECT p.pdt_productid AS ntfproductstockproductid,
    p.pdt_productcode AS ntfproductstockcode,
    ((sum(COALESCE(s.stk_stockquantity, (0)::numeric)) - sum((COALESCE(d.cmd_deliveryquantityserved, (0)::numeric) - COALESCE(d.cmd_deliverylinequantity, (0)::numeric)))) + sum((COALESCE(r.rcp_receptionlinequantityreceived, (0)::numeric) - COALESCE(r.rcp_receptionlinequantityreceived, (0)::numeric)))) AS ntfproductstockquantity,
    p.pdt_productminstock AS ntfproductstockproductthreshold
   FROM (((schema_emswms.pdt_product p
     LEFT JOIN schema_emswms.stk_stock s ON ((p.pdt_productid = s.stk_stockproductid)))
     LEFT JOIN schema_emswms.cmd_deliveryline d ON ((p.pdt_productid = d.cmd_deliverylineproductid)))
     LEFT JOIN schema_emswms.rcp_receptionline r ON ((p.pdt_productid = r.rcp_receptionlineproductid)))
  GROUP BY p.pdt_productid
 HAVING (((sum(COALESCE(s.stk_stockquantity, (0)::numeric)) - sum((COALESCE(d.cmd_deliveryquantityserved, (0)::numeric) - COALESCE(d.cmd_deliverylinequantity, (0)::numeric)))) + sum((COALESCE(r.rcp_receptionlinequantityreceived, (0)::numeric) - COALESCE(r.rcp_receptionlinequantityreceived, (0)::numeric)))) < p.pdt_productminstock);


